package com.example.lending.domain;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

/** 한 책의 예약 줄. 앞에서부터 순서대로 담긴다. */
public class ReservationQueue {

    private final List<Reservation> reservations;

    public ReservationQueue(List<Reservation> reservations) {
        this.reservations = new ArrayList<>(reservations);
    }

    /** 줄 맨 뒤에 세운다. 같은 회원이 두 번 줄 설 수 없다. */
    public Reservation enqueue(UUID bookId, UUID memberId) {
        if (reservations.stream().anyMatch(r -> r.getMemberId().equals(memberId))) {
            throw new AlreadyReservedException(bookId, memberId);
        }
        Reservation reservation = Reservation.start(bookId, memberId);
        reservations.add(reservation);
        return reservation;
    }

    /** 1부터 시작하는 줄에서의 순서. */
    public int positionOf(Reservation reservation) {
        return reservations.indexOf(reservation) + 1;
    }

    /**
     * 예약이 있으면 맨 앞 예약자만 빌릴 수 있다. 빌릴 수 있으면 소진될 예약을 돌려준다.
     * 예약이 없으면 누구나 빌릴 수 있으므로 빈 값을 돌려준다.
     */
    public Optional<Reservation> claimFor(UUID memberId) {
        if (reservations.isEmpty()) {
            return Optional.empty();
        }
        Reservation front = reservations.get(0);
        if (!front.getMemberId().equals(memberId)) {
            throw new ReservedForOtherException(front.getBookId());
        }
        return Optional.of(front);
    }

    public List<Reservation> asList() {
        return List.copyOf(reservations);
    }
}
