package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.ListReservationsUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase.ReserveBookCommand;
import com.example.lending.application.port.in.ReserveBookUseCase.ReservationResult;
import com.example.lending.domain.Reservation;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;
import java.util.stream.IntStream;

@RestController
@RequestMapping("/books/{bookId}/reservations")
public class ReservationController {

    private final ReserveBookUseCase reserveBookUseCase;
    private final ListReservationsUseCase listReservationsUseCase;

    public ReservationController(ReserveBookUseCase reserveBookUseCase,
                                 ListReservationsUseCase listReservationsUseCase) {
        this.reserveBookUseCase = reserveBookUseCase;
        this.listReservationsUseCase = listReservationsUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ReserveBookResponse reserveBook(@PathVariable UUID bookId, @RequestBody ReserveBookRequest request) {
        ReservationResult result = reserveBookUseCase.reserveBook(new ReserveBookCommand(bookId, request.memberId()));
        return new ReserveBookResponse(result.reservation().getId(), result.position());
    }

    @GetMapping
    public List<ReservationResponse> listReservations(@PathVariable UUID bookId) {
        List<Reservation> reservations = listReservationsUseCase.listReservations(bookId);
        return IntStream.range(0, reservations.size())
                .mapToObj(i -> ReservationResponse.from(reservations.get(i), i + 1))
                .toList();
    }
}
